macro_rules! nghttp2_send_data_callback {
    () => {
        # [doc = " @functypedef"] # [doc = ""] # [doc = " Callback function invoked when :enum:`NGHTTP2_DATA_FLAG_NO_COPY` is"] # [doc = " used in :type:`nghttp2_data_source_read_callback` to send complete"] # [doc = " DATA frame."] # [doc = ""] # [doc = " The |frame| is a DATA frame to send.  The |framehd| is the"] # [doc = " serialized frame header (9 bytes). The |length| is the length of"] # [doc = " application data to send (this does not include padding).  The"] # [doc = " |source| is the same pointer passed to"] # [doc = " :type:`nghttp2_data_source_read_callback`."] # [doc = ""] # [doc = " The application first must send frame header |framehd| of length 9"] # [doc = " bytes.  If ``frame->data.padlen > 0``, send 1 byte of value"] # [doc = " ``frame->data.padlen - 1``.  Then send exactly |length| bytes of"] # [doc = " application data.  Finally, if ``frame->data.padlen > 1``, send"] # [doc = " ``frame->data.padlen - 1`` bytes of zero as padding."] # [doc = ""] # [doc = " The application has to send complete DATA frame in this callback."] # [doc = " If all data were written successfully, return 0."] # [doc = ""] # [doc = " If it cannot send any data at all, just return"] # [doc = " :enum:`NGHTTP2_ERR_WOULDBLOCK`; the library will call this callback"] # [doc = " with the same parameters later (It is recommended to send complete"] # [doc = " DATA frame at once in this function to deal with error; if partial"] # [doc = " frame data has already sent, it is impossible to send another data"] # [doc = " in that state, and all we can do is tear down connection).  When"] # [doc = " data is fully processed, but application wants to make"] # [doc = " `nghttp2_session_mem_send()` or `nghttp2_session_send()` return"] # [doc = " immediately without processing next frames, return"] # [doc = " :enum:`NGHTTP2_ERR_PAUSE`.  If application decided to reset this"] # [doc = " stream, return :enum:`NGHTTP2_ERR_TEMPORAL_CALLBACK_FAILURE`, then"] # [doc = " the library will send RST_STREAM with INTERNAL_ERROR as error code."] # [doc = " The application can also return"] # [doc = " :enum:`NGHTTP2_ERR_CALLBACK_FAILURE`, which will result in"] # [doc = " connection closure.  Returning any other value is treated as"] # [doc = " :enum:`NGHTTP2_ERR_CALLBACK_FAILURE` is returned."] pub type nghttp2_send_data_callback = :: std :: option :: Option < unsafe extern "C" fn (session : * mut nghttp2_session , frame : * mut nghttp2_frame , framehd : * const u8 , length : usize , source : * mut nghttp2_data_source , user_data : * mut :: std :: os :: raw :: c_void ,) -> :: std :: os :: raw :: c_int , > ;
    };
}

nghttp2_send_data_callback!();